starter:
def modern_enough(version):
    """True if version is 3.10 or newer."""
    return version >= "3.10"

solution:
def modern_enough(version):
    """True if version is 3.10 or newer."""
    return tuple(int(part) for part in version.split(".")) >= (3, 10)

